def main():
    root=Path(os.environ['PANCANCER_PREFLIGHT_ROOT']);guard=resource(root,2*1024**2);out=root/'NSCLC92_receiver_function_reference_scope_20261019_v1';assert not out.exists();out.mkdir(mode=0o700);refroot=Path(__file__).parent/'hallmark50_public_reference_v3';manifest=refroot/'reference_provenance.json';oldplan=root/'immune_RNA_MCP_functional_description_20261018_v1/plan_before_complete_functional_description.json';assert sha(manifest)==json.loads(oldplan.read_text())['public_reference_manifest_sha256'];records=json.loads(manifest.read_text())['records'];assert len(records)==50
    proof=root/'NSCLC_frozen92_axis_source_result_audit_20261019_v1/private_terminal.json';assert sha(proof)=='79e8aa29aec12db05d437f6e4ebc24dec7e97772bf62ca594434efe36522b9b7';save=lambda n,d:(out/n).write_text(json.dumps(d,indent=2)+'\n')
    save('plan_before_receiver_reference_gene_qualification.json',dict(created_UTC=datetime.now(timezone.utc).isoformat(),source_sha256=sha(__file__),resource_guard=guard,all_reference_positions=50,public_reference_manifest_sha256=sha(manifest),scope='All50existing publicHallmarks. Follow existing mainBH-only candidate(s) as exploratory receiver-state questions, not new validated mechanisms. No function/correlation/clinicalP selection of references. Exclude complete1840LRnative gene universe, not merely current two-component axis genes.',mapping='Uppercase exact unique native symbols only; ambiguous/missing retained as reasons, no new aliases. Report retained-reference fraction and measured fraction; >=20unique native genes and>=80percent measured remaining genes qualifies complement measurement. >=80percent original-reference retained is separately stronger pathway-representation flag, not implied by complement eligibility.',limits='Only gene definitions and cached-shape metadata, no new gene-expression measurement or functional inference. Raw verification provenance for newly used nonLRgenes must be inspected before scores. A disjoint complement is not automatically full pathway activation or formal cell-state annotation.'))
