        path=refroot/(record['name']+'.json');assert sha(path)==record['sha256'];full=sorted({str(g).strip().upper() for g in json.loads(path.read_text())[record['name']]['geneSymbols']});removed=[g for g in full if g in blocked_symbols or lookup.get(g,-1) in blocked_columns];remaining=sorted(set(full)-set(removed));mapped={g:lookup[g] for g in remaining if g in lookup};missing=[g for g in remaining if count[g]==0];ambiguous=[g for g in remaining if count[g]>1];retention=len(remaining)/len(full);measured=len(mapped)/len(remaining) if remaining else 0.;eligible=len(mapped)>=20 and measured>=.8;strong=eligible and retention>=.8;assert not set(mapped.values())&blocked_columns
        definitions.append(dict(reference=record['name'],public_reference_sha256=record['sha256'],full_reference_genes=full,excluded_all_LR_symbols=removed,remaining_genes=remaining,unique_native_columns=mapped,missing_source_symbols=missing,ambiguous_source_symbols=ambiguous,complement_measurement_eligible=eligible,strong_reference_representation=strong));summary.append(dict(reference=record['name'],original_genes=len(full),excluded_LR_genes=len(removed),remaining_genes=len(remaining),uniquely_measured_genes=len(mapped),retained_fraction=retention,remaining_gene_measurement_fraction=measured,complement_measurement_eligible=eligible,strong_reference_representation=strong,status='STRONG_REFERENCE_REPRESENTATION_DISJOINT_COMPLEMENT' if strong else 'LOWER_RETENTION_COMPLEMENT_ONLY_NOT_FULL_PATHWAY' if eligible else 'COMPLEMENT_GENE_COVERAGE_INSUFFICIENT'))
